import{_ as e,a as r,c as a,ac as d}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"把《周易》读进具体问题：乾坤、泰否、既济未济对读","description":"通过六卦经传对照、原创生活案例、反例和复盘模板，练习有依据的经典阅读，区分原文说明与现代类比。","frontmatter":{"title":"把《周易》读进具体问题：乾坤、泰否、既济未济对读","description":"通过六卦经传对照、原创生活案例、反例和复盘模板，练习有依据的经典阅读，区分原文说明与现代类比。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"易经专题","summary":"通过六卦经传对照、原创生活案例、反例和复盘模板，练习有依据的经典阅读，区分原文说明与现代类比。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"易经：后世易学与术数分界","link":"/life/personal/yijing/traditions"},"next":{"text":"易经：术语、读音与常见误解","link":"/life/personal/yijing/glossary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"易经：后世易学与术数分界","link":"/life/personal/yijing/traditions"},"next":{"text":"易经：术语、读音与常见误解","link":"/life/personal/yijing/glossary"}},"headers":[],"relativePath":"life/personal/yijing/reading-practice.md","filePath":"life/personal/yijing/reading-practice.md"}'),i={name:"life/personal/yijing/reading-practice.md"};function n(o,t,l,s,p,h){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="把《周易》读进具体问题-乾坤、泰否、既济未济对读" tabindex="-1">把《周易》读进具体问题：乾坤、泰否、既济未济对读 <a class="header-anchor" href="#把《周易》读进具体问题-乾坤、泰否、既济未济对读" aria-label="Permalink to &quot;把《周易》读进具体问题：乾坤、泰否、既济未济对读&quot;">​</a></h1><p>本篇不从随机起卦开始，而从读懂文本开始。六卦按乾坤、泰否、既济未济三组对读：第一组看行动与承载，第二组看交流与阻隔，第三组看完成与未完成。每组都先分经传，再提出可检查的现代问题，最后给出一个不应套用的反例。</p><p>这些主题是阅读组织方式，不表示每卦只含一个意思，也不表示六卦组成了所有人必经的生命周期。先不熟悉经、传的读者，可看<a href="/life/personal/yijing/text-history">文本层次</a>；想理解传文各自功能，可看<a href="/life/personal/yijing/ten-wings">十翼逐篇阅读</a>。</p><h2 id="一次读卦的五步" tabindex="-1">一次读卦的五步 <a class="header-anchor" href="#一次读卦的五步" aria-label="Permalink to &quot;一次读卦的五步&quot;">​</a></h2><ol><li>写下卦名、上下卦，画清六爻，自下而上标位置。</li><li>只读卦辞和爻辞，圈出人物、物象、动作、条件和判断。</li><li>补读《彖》、大象、小象，注明传文增加了什么解释。</li><li>查一至两家注释，记录确实存在的分歧，不拼凑成虚假的一致。</li><li>写一个现代例子和一个反例，说明类比在哪个条件下成立。</li></ol><p>第五步特别重要。只会讲正面例子，常常意味着规则过宽，几乎任何事情都能被说成符合。能够指出“不适用于这里”，才说明自己真正理解了文本的约束。</p><h2 id="第一组-乾——行动有阶段-积极也有边界" tabindex="-1">第一组：乾——行动有阶段，积极也有边界 <a class="header-anchor" href="#第一组-乾——行动有阶段-积极也有边界" aria-label="Permalink to &quot;第一组：乾——行动有阶段，积极也有边界&quot;">​</a></h2><p>乾卦六爻皆阳。先读它的主要图景：潜龙、见龙、终日乾乾、或跃、飞龙、亢龙。这里既有行动展开，也有不宜使用、警惕、未定与过度的限制。因此把乾简单概括为“一直向上冲”，会漏掉几条最关键的爻辞。</p><table tabindex="0"><thead><tr><th>原文位置</th><th>可先把握的文本信息</th><th>不宜直接添加的含义</th></tr></thead><tbody><tr><td>初九“潜龙勿用”</td><td>尚宜潜藏，有行动限制</td><td>某年龄前一律不许出头</td></tr><tr><td>九三“终日乾乾”“夕惕”</td><td>勤勉与警惕相连</td><td>任何时候加班越久越好</td></tr><tr><td>九四“或跃在渊”</td><td>行动未定，存在试探空间</td><td>只要冒险就能成功</td></tr><tr><td>上九“亢龙有悔”</td><td>过高过极与悔相连</td><td>取得成绩本身就是错误</td></tr></tbody></table><p>《大象》的“自强不息”给出修养方向，《文言》则反复讨论进退、存亡、得丧。把它们合起来读，可以看到自强不等于不承认限度。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%9C%AC%E7%BE%A9_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%8D%B71" target="_blank" rel="noopener noreferrer">乾卦相关经传与朱熹注</a>。</p><p><strong>原创练习：学习新技能。</strong> 一个人计划一个月内做出小作品。第一周练基础，第二周做可运行的最小练习，第三周请人指出问题，第四周修订并展示。可以用潜、见、惕、自试来帮助描述不同动作，但不可把每周硬说成某一爻的命定阶段。真正支持计划的证据，是练习完成度、反馈和剩余时间。</p><p><strong>反例。</strong> 对已经具备能力、且只需尝试一个低风险任务的人，继续以“潜龙勿用”劝其永远等待，可能只是扩大恐惧。判断是否宜潜，需要说明能力缺口或风险，而不是只给一句古语。</p><h2 id="第一组-坤——承载、成事与柔中有刚" tabindex="-1">第一组：坤——承载、成事与柔中有刚 <a class="header-anchor" href="#第一组-坤——承载、成事与柔中有刚" aria-label="Permalink to &quot;第一组：坤——承载、成事与柔中有刚&quot;">​</a></h2><p>坤卦六爻皆阴，卦辞谈牝马之贞、攸往、得朋、安贞。六爻中有履霜、直方大、含章、括囊、黄裳和龙战等意象。即使把坤的基本德性理解为顺，也不能把这些具体差别全部抹掉。</p><p>《文言》说“坤至柔而动也刚”，大象说“厚德载物”。这里的柔顺可以是承接条件、容纳与成就事务，不等于无条件服从。卦中的“括囊，无咎无誉”还提示一种收敛言行的处境，但无誉也意味着并非所有评价都指向出名或被赞赏。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%A4" target="_blank" rel="noopener noreferrer">坤卦经传</a>。</p><p><strong>原创练习：共同旅行。</strong> 有人提出目的地，有人核对路线，有人负责住宿和时间安排。后两类工作常不显眼，却决定旅行能否成行。借“载物”反思，可以看见支持工作的价值，同时明确各人的付出和边界。</p><p><strong>反例。</strong> 若有人以“你要像坤一样顺”要求同伴承担全部琐事、放弃意见，这不是由文本自动得出的合理分工。现代合作仍需协商、同意与公平安排。乾坤也不应被固定分配给男性与女性；主动和承载是每个人都可能需要的能力。</p><h3 id="乾坤合读的小问题" tabindex="-1">乾坤合读的小问题 <a class="header-anchor" href="#乾坤合读的小问题" aria-label="Permalink to &quot;乾坤合读的小问题&quot;">​</a></h3><p>这件事缺的是发起，还是维持？哪一种贡献被忽略了？有没有因为追求表面成就而把基础工作交给别人承担？这些问题比给自己判定“我是乾型人”更有解释力。</p><h2 id="第二组-泰——通达不是没有条件" tabindex="-1">第二组：泰——通达不是没有条件 <a class="header-anchor" href="#第二组-泰——通达不是没有条件" aria-label="Permalink to &quot;第二组：泰——通达不是没有条件&quot;">​</a></h2><p>泰是乾下坤上，卦辞说“小往大来，吉亨”。《彖》用天地交、上下交来说明它的通达。这里容易遇到的疑问是：为什么地在上、天在下反而叫交？在传统解释中，关注的是两种力量能否相接和往来，不是要求卦画直接复制肉眼所见的天空地面位置。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B3%B0" target="_blank" rel="noopener noreferrer">泰卦经传</a>。</p><p>但泰卦内部并不全是欢庆。九三说“无平不陂，无往不复”，上六更有“城复于隍”。把整个泰卦视为一张永久好运保证书，就无法解释这些爻辞。</p><table tabindex="0"><thead><tr><th>阅读层次</th><th>泰卦中的内容</th><th>提醒的问题</th></tr></thead><tbody><tr><td>卦辞</td><td>吉亨</td><td>当前通达的整体判断</td></tr><tr><td>《彖》</td><td>上下交而其志同</td><td>通达依靠怎样的关系</td></tr><tr><td>九三</td><td>无平不陂，无往不复</td><td>怎样理解顺利中的变动</td></tr><tr><td>上六</td><td>城复于隍</td><td>支撑结构失效时如何应对</td></tr></tbody></table><p><strong>原创练习：小组合作。</strong> 小组成员能及时提出困难，负责人能调整任务，信息也能从执行者回到决策者。可以用“上下交”帮助描述这种沟通，但要继续记录：回应是否及时，问题是否被解决，任务是否仍有人接手。只说“气场很通”没有提供可以复盘的内容。</p><p><strong>反例。</strong> 一段关系表面没有争论，可能因为弱势一方不敢说话。没有冲突声不等于上下交。用泰来评价关系前，要先看不同意见能否被表达。</p><h2 id="第二组-否——阻塞中的区分与行动" tabindex="-1">第二组：否——阻塞中的区分与行动 <a class="header-anchor" href="#第二组-否——阻塞中的区分与行动" aria-label="Permalink to &quot;第二组：否——阻塞中的区分与行动&quot;">​</a></h2><p>否是坤下乾上，与泰交换了上下卦。《彖》讲天地不交、上下不交；大象强调俭德避难。这个主题可以帮助辨认沟通阻塞、价值不合或不宜冒进的处境，但否卦后面也有“休否”“倾否，先否后喜”。它不是一句永不改变的坏消息。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%A6" target="_blank" rel="noopener noreferrer">否卦经传</a>。</p><p>九五“其亡其亡，系于苞桑”被《系辞下》引来讨论安不忘危。因此它可以与泰的九三、既济的大象一同读：困境改善时仍须注意维持改善的条件，而不是一见转机便停止检查。</p><p><strong>原创练习：无法推进的沟通。</strong> 某个共同计划反复讨论没有结果。先分别写目标差异、信息缺口、决定权限与不可让步条件，再决定是补充信息、调整目标还是暂缓。借否卦组织提问，并不需要假设某人属于“小人”，更不需要把反对意见先判成恶意。</p><p><strong>反例。</strong> 如果只是自己不喜欢听到批评，就把对方叫作造成否塞的小人，经典成了自我保护工具。应先问批评是否指出了事实错误。古经中的君子、小人语汇，也有不同语境和解释，不能直接拿来给现实熟人贴永久道德标签。</p><h3 id="泰否合读的小问题" tabindex="-1">泰否合读的小问题 <a class="header-anchor" href="#泰否合读的小问题" aria-label="Permalink to &quot;泰否合读的小问题&quot;">​</a></h3><p>相同的人和资源，为什么换一种沟通方式就会产生不同结果？目前的顺畅由什么维持，阻塞又在哪一环发生？“否极泰来”可以成为希望性的概括，但不能代替行动条件，更不能据它推算某天必然转好。</p><h2 id="第三组-既济——完成以后-还有什么工作" tabindex="-1">第三组：既济——完成以后，还有什么工作 <a class="header-anchor" href="#第三组-既济——完成以后-还有什么工作" aria-label="Permalink to &quot;第三组：既济——完成以后，还有什么工作&quot;">​</a></h2><p>既济是离下坎上，水在火上。卦辞包括“初吉终乱”，大象说“君子以思患而豫防之”。“既”有已经之意，“济”有渡、成之意；完成却仍要预防失序，是本卦非常值得细读的张力。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A2%E6%BF%9F" target="_blank" rel="noopener noreferrer">既济卦经传</a>。</p><p>按通常的爻位解释，既济六爻全部当位；这正好反驳“当位就永远吉”的简化说法。爻位关系是一项解释线索，不是足以覆盖全部辞句的结论。</p><p>九五把盛大的杀牛祭与较简的禴祭相比较，也提示形式、时宜和实际意义未必一致。阅读这个对照，应先承认其古代祭祀语境；转到现代，只能借它提问“投入是否用在合适之处”，不能把祭祀判断直接当成现代效率公式。</p><p><strong>原创练习：读完一本书。</strong> 合上最后一页可以叫完成阅读，但理解是否稳固，还要看能否复述观点、解释例子、识别反例。为已完成的阅读安排一次回顾，是“预防遗忘”的现代应用，不是既济卦已经许诺记忆永远可靠。</p><p><strong>反例。</strong> 有人因此把所有完成都理解为马上要失败，始终不敢结束任务。这也过度。既济提示保持必要维护，不要求把任何成果一笔抹杀，更不要求无限检查。</p><h2 id="第三组-未济——未完成-不代表没有希望" tabindex="-1">第三组：未济——未完成，不代表没有希望 <a class="header-anchor" href="#第三组-未济——未完成-不代表没有希望" aria-label="Permalink to &quot;第三组：未济——未完成，不代表没有希望&quot;">​</a></h2><p>未济是坎下离上，火在水上。卦辞一面说亨，一面以小狐几乎渡过却濡尾说明不能续终的问题；大象要求“慎辨物居方”。从完成度看仍有欠缺，从行动可能看又不是绝望。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%9C%AA%E6%BF%9F" target="_blank" rel="noopener noreferrer">未济卦经传</a>。</p><p>未济六爻按常用爻位规则都不当位，《彖》却指出刚柔相应。它与既济形成一个很好的教学反例：位置合宜不自动消除变化，位置未合也不自动取消合作可能。</p><p><strong>原创练习：一份初稿。</strong> 初稿已有主要内容，但论据、结构和来源尚待检查。先分别列出已经完成和没有完成的部分，再决定补证据、重排还是删去无法支持的结论。不要因为写了很多就直接宣布成稿，也不要因仍有缺口便认为全部劳动无用。</p><p><strong>反例。</strong> 若已经达到事前确定的质量标准，仍以“人生总是未济”为理由不断重开任务，也会使事情无法交付。古典关于持续变化的思考，不取消现代任务所需的明确完成标准。</p><h3 id="既济未济合读的小问题" tabindex="-1">既济未济合读的小问题 <a class="header-anchor" href="#既济未济合读的小问题" aria-label="Permalink to &quot;既济未济合读的小问题&quot;">​</a></h3><p>什么意义上已经完成，什么意义上仍未完成？完成后有哪些必要维护？剩余问题是否影响当前目标？把这些写成事实，比只问“这是好卦还是坏卦”更能帮助行动。</p><h2 id="一份七天阅读安排" tabindex="-1">一份七天阅读安排 <a class="header-anchor" href="#一份七天阅读安排" aria-label="Permalink to &quot;一份七天阅读安排&quot;">​</a></h2><table tabindex="0"><thead><tr><th>天数</th><th>阅读内容</th><th>当天产出</th></tr></thead><tbody><tr><td>第一天</td><td>乾卦卦爻辞与大象</td><td>六爻动作表，写出两种不宜冒进的条件</td></tr><tr><td>第二天</td><td>坤卦与《文言》相关段</td><td>区分承载、协作与无条件服从</td></tr><tr><td>第三天</td><td>泰的卦辞、九三、上六</td><td>列顺利得以维持的三个条件</td></tr><tr><td>第四天</td><td>否的卦辞、九五、上九</td><td>区分事实阻塞与个人不满</td></tr><tr><td>第五天</td><td>既济经传</td><td>写一项完成后的必要维护</td></tr><tr><td>第六天</td><td>未济经传</td><td>列完成项、未完成项及交付标准</td></tr><tr><td>第七天</td><td>对照任意两家注本</td><td>做一张同句异解卡并写一个反例</td></tr></tbody></table><p>这是一份阅读练习，不需要每天起卦，也不以获得某种神秘体验为学习成果。若感兴趣，可另外读<a href="/life/personal/yijing/divination">筮法与算法边界</a>，先掌握从六个数到卦变的核算，再讨论解释。</p><h2 id="复盘模板-把自己的话和古人的话分栏" tabindex="-1">复盘模板：把自己的话和古人的话分栏 <a class="header-anchor" href="#复盘模板-把自己的话和古人的话分栏" aria-label="Permalink to &quot;复盘模板：把自己的话和古人的话分栏&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>写法示例</th></tr></thead><tbody><tr><td>原文出处</td><td>既济大象“思患而豫防之”</td></tr><tr><td>古典语境</td><td>已济之时仍需防范失序</td></tr><tr><td>我的类比</td><td>阅读完成后安排复述</td></tr><tr><td>类比依据</td><td>完成一次阅读不等于长期记住</td></tr><tr><td>现实证据</td><td>一周后能否独立解释三个要点</td></tr><tr><td>不适用处</td><td>不能据此认为所有完成都会失败</td></tr><tr><td>下次行动</td><td>周末用十分钟写一次无提示回顾</td></tr></tbody></table><p>本篇逐一核读了六卦的相关卦爻辞和传文；乾卦同时参照朱熹《本义》。全部现代案例、七天安排与模板均为本专题原创，不冒充古籍记载或真实占验。进一步可读<a href="/life/personal/yijing/commentaries">历代注家比较</a>和<a href="/life/personal/yijing/philosophy">时位、中正、变通</a>。<a href="/life/personal/yijing/overview">返回易经专题</a>。</p>',51)])])}const f=e(i,[["render",n]]);export{c as __pageData,f as default};
